import{_ as a,o,c as t,a0 as l}from"./chunks/framework.DqMqoJl9.js";const i="/assets/10-heap_20210527100517.DI6H_nkl.png",r="/assets/10-heap_20210527131929.CGSmsDz2.png",c="/assets/10-heap_20210527203303.CA6iRgdK.png",d="/assets/10-heap_20210527203320.DKT3kubh.png",p="/assets/10-heap_20210527220614.BmQytkdz.png",s="/assets/10-heap_20210527230922.kK8NDhNJ.png",h="/assets/10-heap_20210527231606.pVq6woNy.png",n="/assets/10-heap_20210528120236.DVLwoGkC.png",_="/assets/10-heap_20210528120508.CTVw8Af9.png",x=JSON.parse('{"title":"堆","description":"","frontmatter":{},"headers":[],"relativePath":"algorithm/10-heap.md","filePath":"algorithm/10-heap.md","lastUpdated":1791573371000}'),u={name:"algorithm/10-heap.md"};function b(q,e,m,k,f,g){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="堆" tabindex="-1">堆 <a class="header-anchor" href="#堆" aria-label="Permalink to &quot;堆&quot;">​</a></h1><h2 id="_1-概念" tabindex="-1">1 概念 <a class="header-anchor" href="#_1-概念" aria-label="Permalink to &quot;1 概念&quot;">​</a></h2><h3 id="_1-1-堆的结构" tabindex="-1">1.1 堆的结构 <a class="header-anchor" href="#_1-1-堆的结构" aria-label="Permalink to &quot;1.1 堆的结构&quot;">​</a></h3><ul><li>堆是一个完全二叉树</li><li>堆中每一个节点的值都必须大于等于（或小于等于）其子树中每个节点的值</li><li>对于每个节点的值都大于等于子树中每个节点值的堆，我们叫作“大顶堆”。对于每个节点的值都小于等于子树中每个节点值的堆，我们叫作“小顶堆”</li></ul><p>叶子节点都在最底下两层，最后一层的叶子节点都靠左排列，并且除了最后一层，其他层的节点个数都要达到最大，这种二叉树叫作完全二叉树</p><p><img src="'+i+'" alt=""></p><p>其中第 1 个和第 2 个是大顶堆，第 3 个是小顶堆，第 4 个不是堆。除此之外，从图中还可以看出来，对于同一组数据，我们可以构建多种不同形态的堆</p><h3 id="_1-2-堆的存储" tabindex="-1">1.2 堆的存储 <a class="header-anchor" href="#_1-2-堆的存储" aria-label="Permalink to &quot;1.2 堆的存储&quot;">​</a></h3><p>堆使用数组存储</p><p>为计算方便，一般从下标 1 开始存储</p><p><img src="'+r+'" alt=""></p><p>访问节点：</p><ul><li>数组中下标为 <code>i</code> 的节点的左子节点，就是下标为 <code>i∗2</code> 的节点</li><li>右子节点就是下标为 <code>i∗2+1</code> 的节点</li><li>父节点就是下标为 <code>i/2</code> 的节点</li></ul><h2 id="_2-堆相关操作" tabindex="-1">2 堆相关操作 <a class="header-anchor" href="#_2-堆相关操作" aria-label="Permalink to &quot;2 堆相关操作&quot;">​</a></h2><h3 id="_2-1-往堆中插入一个元素-堆化" tabindex="-1">2.1 往堆中插入一个元素 (堆化) <a class="header-anchor" href="#_2-1-往堆中插入一个元素-堆化" aria-label="Permalink to &quot;2.1 往堆中插入一个元素 (堆化)&quot;">​</a></h3><p>堆化实际上有两种，<code>从下往上</code> 和 <code>从上往下</code>。这里展示 <code>从下往上</code> 的堆化方法</p><p><img src="'+c+'" alt=""></p><blockquote><p>堆化就是顺着节点所在的路径，向上或者向下，对比，然后交换</p></blockquote><p><img src="'+d+'" alt=""></p><h3 id="_2-2-删除堆顶元素" tabindex="-1">2.2 删除堆顶元素 <a class="header-anchor" href="#_2-2-删除堆顶元素" aria-label="Permalink to &quot;2.2 删除堆顶元素&quot;">​</a></h3><p>把最后一个节点放到堆顶，然后利用同样的父子节点对比方法</p><p><img src="'+p+'" alt=""></p><h3 id="_2-3-建堆" tabindex="-1">2.3 建堆 <a class="header-anchor" href="#_2-3-建堆" aria-label="Permalink to &quot;2.3 建堆&quot;">​</a></h3><p>建堆可以不借助另一个数组，就在原数组上操作。从后往前处理数组，并且每个数据都是从上往下堆化</p><p>从第一个非叶子节点开始，依次堆化</p><blockquote><p>对于完全二叉树来说，下标从 <code>n/2+1</code> 到 <code>n</code> 的节点都是叶子节点。下标从 <code>n/2</code> 开始到 <code>1</code> 的数据为非叶子节点</p></blockquote><p><img src="'+s+'" alt=""></p><blockquote><p>堆排序的建堆过程的时间复杂度是 <code>O(n)</code></p></blockquote><h3 id="_2-4-堆排序" tabindex="-1">2.4 堆排序 <a class="header-anchor" href="#_2-4-堆排序" aria-label="Permalink to &quot;2.4 堆排序&quot;">​</a></h3><p>数组中的第一个元素就是堆顶，也就是最大的元素。我们把它跟最后一个元素交换，那最大元素就放到了下标为 n 的位置</p><p>类似删除堆顶元素的操作，一直重复这个过程，直到最后堆中只剩下标为 1 的一个元素，排序工作就完成了</p><p><img src="'+h+'" alt=""></p><blockquote><p>建堆过程的时间复杂度是 <code>O(n)</code>，排序过程的时间复杂度是 <code>O(n log n)</code>，所以，堆排序整体的时间复杂度是 <code>O(n log n)</code></p></blockquote><h2 id="_3-堆的应用" tabindex="-1">3 堆的应用 <a class="header-anchor" href="#_3-堆的应用" aria-label="Permalink to &quot;3 堆的应用&quot;">​</a></h2><h3 id="_3-1-优先级队列" tabindex="-1">3.1 优先级队列 <a class="header-anchor" href="#_3-1-优先级队列" aria-label="Permalink to &quot;3.1 优先级队列&quot;">​</a></h3><p>队列最大的特性就是先进先出。不过，在优先级队列中，数据的出队顺序不是先进先出，而是按照优先级来，优先级最高的，最先出队</p><p>堆和优先级队列非常相似。一个堆就可以看作一个优先级队列</p><blockquote><p>往优先级队列中插入一个元素，就相当于往堆中插入一个元素；从优先级队列中取出优先级最高的元素，就相当于取出堆顶元素</p></blockquote><h3 id="_3-2-求-top-k" tabindex="-1">3.2 求 Top K <a class="header-anchor" href="#_3-2-求-top-k" aria-label="Permalink to &quot;3.2 求 Top K&quot;">​</a></h3><p>实现步骤：</p><ol><li>创建一个大小为 <code>K</code> 的小顶堆</li><li>顺序遍历数组，从数组中取出取数据与堆顶元素比较</li><li>如果比堆顶元素大，我们就把堆顶元素删除，并且将这个元素插入到堆中</li><li>如果比堆顶元素小，则不做处理，继续遍历数组</li><li>等数组中的数据都遍历完之后，堆中的数据就是前 <code>K</code> 大数据了</li></ol><h3 id="_3-3-利用堆求中位数" tabindex="-1">3.3 利用堆求中位数 <a class="header-anchor" href="#_3-3-利用堆求中位数" aria-label="Permalink to &quot;3.3 利用堆求中位数&quot;">​</a></h3><p>对于一组静态数据，中位数是固定的，我们可以先排序，第 n2 个数据就是中位数</p><p>如果是动态数据集合，中位数在不停地变动，如果再用先排序的方法，每次询问中位数的时候，都要先进行排序，那效率就不高了</p><blockquote><p>借助堆这种数据结构，我们不用排序，就可以非常高效地实现求中位数操作</p></blockquote><p>实现步骤：</p><ol><li>需要维护两个堆，一个大顶堆，一个小顶堆。大顶堆中存储前半部分数据，小顶堆中存储后半部分数据，且小顶堆中的数据都大于大顶堆中的数据</li><li>前 <code>n/2</code> 个数据存储在大顶堆中，后 <code>n/2</code> 个数据存储在小顶堆中 <img src="'+n+'" alt=""></li><li>如果新加入的数据小于等于大顶堆的堆顶元素，我们就将这个新数据插入到大顶堆；如果新加入的数据大于等于小顶堆的堆顶元素，我们就将这个新数据插入到小顶堆</li><li>如果出现两个堆数据个数不一致的情况，可以从一个堆中不停地将堆顶元素移动到另一个堆 <img src="'+_+'" alt=""></li><li>插入数据因为需要涉及堆化，所以时间复杂度变成了 <code>O(log n)</code></li><li>求中位数我们只需要返回大顶堆的堆顶元素就可以了</li></ol><blockquote><p>利用两个堆不仅可以快速求出中位数，还可以快速求其他百分位的数据，原理是类似的。</p></blockquote><h2 id="_4-javascript-中的堆" tabindex="-1">4 JavaScript 中的堆 <a class="header-anchor" href="#_4-javascript-中的堆" aria-label="Permalink to &quot;4 JavaScript 中的堆&quot;">​</a></h2><h2 id="_5-实例" tabindex="-1">5 实例 <a class="header-anchor" href="#_5-实例" aria-label="Permalink to &quot;5 实例&quot;">​</a></h2><h3 id="_5-1-leetcode-215-数组中的第-k-个最大元素" tabindex="-1">5.1 LeetCode 215 数组中的第 K 个最大元素 <a class="header-anchor" href="#_5-1-leetcode-215-数组中的第-k-个最大元素" aria-label="Permalink to &quot;5.1 LeetCode 215 数组中的第 K 个最大元素&quot;">​</a></h3><h3 id="_5-2-leetcode-347-前-k-个高频元素" tabindex="-1">5.2 LeetCode 347 前 K 个高频元素 <a class="header-anchor" href="#_5-2-leetcode-347-前-k-个高频元素" aria-label="Permalink to &quot;5.2 LeetCode 347 前 K 个高频元素&quot;">​</a></h3><h3 id="_5-3-leetcode-23-合并-k-个排序链表" tabindex="-1">5.3 LeetCode 23 合并 K 个排序链表 <a class="header-anchor" href="#_5-3-leetcode-23-合并-k-个排序链表" aria-label="Permalink to &quot;5.3 LeetCode 23 合并 K 个排序链表&quot;">​</a></h3>',53)])])}const K=a(u,[["render",b]]);export{x as __pageData,K as default};
